private handleEscalation = async (incidentId: string) => {
    try {
        // Get the incident details
        const incident = await this.incidentsRepository.findById(incidentId);
        if (!incident) {
            this.logger.warn({
                service: SERVICE_NAME,
                method: "handleEscalation",
                message: `Incident ${incidentId} not found for escalation`
            });
            return;
        }

        // Get the monitor to access notification settings
        const monitor = await this.monitorsRepository.findById(incident.monitorId, incident.teamId);
        if (!monitor) {
            this.logger.warn({
                service: SERVICE_NAME,
                method: "handleEscalation",
                message: `Monitor ${incident.monitorId} not found for incident ${incidentId}`
            });
            return;
        }

        // Cancel any existing escalation timers for this incident
        this.cancelEscalation(incidentId);

        // Define escalation levels with configurable timing (in milliseconds)
        const escalationLevels = [
            { delay: 5 * 60 * 1000, level: 1, description: "First escalation" },     // 5 minutes
            { delay: 15 * 60 * 1000, level: 2, description: "Second escalation" },   // 15 minutes  
            { delay: 30 * 60 * 1000, level: 3, description: "Third escalation" },    // 30 minutes
            { delay: 60 * 60 * 1000, level: 4, description: "Final escalation" }     // 1 hour
        ];

        const timers: NodeJS.Timeout[] = [];

        for (const escalation of escalationLevels) {
            const timer = setTimeout(async () => {
                try {
                    // Check if incident is still active before sending escalation
                    const currentIncident = await this.incidentsRepository.findById(incidentId);
                    if (!currentIncident || !currentIncident.status) {
                        this.logger.debug({
                            service: SERVICE_NAME,
                            method: "handleEscalation",
                            message: `Skipping escalation for resolved incident ${incidentId}`
                        });
                        return;
                    }

                    // Build escalation message
                    const escalationMessage = this.buildEscalationMessage(monitor, incident, escalation);

                    // Send notifications through existing notification service
                    const success = await this.sendEscalationNotifications(monitor, escalationMessage);

                    this.logger.info({
                        service: SERVICE_NAME,
                        method: "handleEscalation",
                        message: `Escalation level ${escalation.level} sent for incident ${incidentId}`,
                        details: { success, level: escalation.level, delay: escalation.delay }
                    });

                } catch (error) {
                    this.logger.error({
                        service: SERVICE_NAME,
                        method: "handleEscalation",
                        message: `Failed to send escalation level ${escalation.level} for incident ${incidentId}`,
                        details: { error: error instanceof Error ? error.message : 'Unknown error' },
                        stack: error instanceof Error ? error.stack : undefined
                    });
                }
            }, escalation.delay);

            timers.push(timer);
        }

        // Store timers for this incident so they can be cancelled later
        this.escalationTimers.set(incidentId, timers);

        this.logger.debug({
            service: SERVICE_NAME,
            method: "handleEscalation",
            message: `Escalation timers set for incident ${incidentId}`,
            details: { levels: escalationLevels.length }
        });

    } catch (error) {
        this.logger.error({
            service: SERVICE_NAME,
            method: "handleEscalation",
            message: `Failed to setup escalation for incident ${incidentId}`,
            details: { error: error instanceof Error ? error.message : 'Unknown error' },
            stack: error instanceof Error ? error.stack : undefined
        });
    }
};

// Add method to cancel escalation timers
private cancelEscalation = (incidentId: string) => {
    const timers = this.escalationTimers.get(incidentId);
    if (timers) {
        timers.forEach(timer => clearTimeout(timer));
        this.escalationTimers.delete(incidentId);

        this.logger.debug({
            service: SERVICE_NAME,
            method: "cancelEscalation",
            message: `Cancelled escalation timers for incident ${incidentId}`
        });
    }
};

// Add method to build escalation message
private buildEscalationMessage = (monitor: Monitor, incident: Incident, escalation: { level: number, description: string }): NotificationMessage => {
    const message = `🚨 **ESCALATION LEVEL ${escalation.level}** 🚨\n\n` +
        `Monitor: ${monitor.name || monitor.url}\n` +
        `Incident: ${incident.message || 'Service unavailable'}\n` +
        `Status Code: ${incident.statusCode || 'N/A'}\n` +
        `Started: ${new Date(incident.startTime).toISOString()}\n` +
        `Duration: ${Math.floor((Date.now() - new Date(incident.startTime).getTime()) / 1000 / 60)} minutes\n\n` +
        `${escalation.description} - Immediate attention required!`;

    return {
        subject: `ESCALATION: ${monitor.name || monitor.url} - Level ${escalation.level}`,
        body: message,
        incidentInfo: {
            incidentId: incident.id,
            monitorId: monitor.id,
            statusCode: incident.statusCode,
            message: incident.message
        }
    };
};

// Add method to send escalation notifications
private sendEscalationNotifications = async (monitor: Monitor, message: NotificationMessage): Promise<boolean> => {
    const notificationIds = monitor.notifications ?? [];
    if (notificationIds.length === 0) {
        this.logger.warn({
            service: SERVICE_NAME,
            method: "sendEscalationNotifications",
            message: `No notifications configured for monitor ${monitor.id}`
        });
        return false;
    }

    const notifications = await this.notificationsService.findNotificationsByTeamId(monitor.teamId);
    const relevantNotifications = notifications.filter(n => notificationIds.includes(n.id));

    if (relevantNotifications.length === 0) {
        this.logger.warn({
            service: SERVICE_NAME,
            method: "sendEscalationNotifications",
            message: `No valid notifications found for monitor ${monitor.id}`
        });
        return false;
    }

    // Send to all configured notification channels
    const results = await Promise.allSettled(
        relevantNotifications.map(notification => 
            this.sendToNotificationProvider(notification, message)
        )
    );

    const successes = results.filter(r => r.status === 'fulfilled' && r.value).length;
    const failures = results.length - successes;

    if (failures > 0) {
        this.logger.warn({
            service: SERVICE_NAME,
            method: "sendEscalationNotifications",
            message: `Escalation notification completed with ${successes} success, ${failures} failure(s)`
        });
    }

    return successes > 0;
};

// Add method to send to individual notification provider
private sendToNotificationProvider = async (notification: Notification, message: NotificationMessage): Promise<boolean> => {
    try {
        // Use the existing notification service's send method
        // We need to create a mock decision object for escalation
        const mockDecision = {
            shouldSendNotification: true,
            incidentReason: "escalation"
        };

        // Create a minimal monitor status response for escalation
        const mockMonitorStatusResponse = {
            status: "down",
            responseTime: 0,
            statusCode: 0,
            message: "Escalation triggered"
        };

        return await this.notificationsService.handleNotifications(
            { ...notification, notifications: [notification.id] } as any,
            mockMonitorStatusResponse,
            mockDecision as any
        );
    } catch (error) {
        this.logger.error({
            service: SERVICE_NAME,
            method: "sendToNotificationProvider",
            message: `Failed to send escalation to ${notification.type}`,
            details: { notificationId: notification.id, error: error instanceof Error ? error.message : 'Unknown error' }
        });
        return false;
    }
};
