    const failures = results.length - successes;

    if (failures > 0) {
        this.logger.warn({
            service: SERVICE_NAME,
            method: "sendEscalationNotifications",
            message: `Escalation notification completed with ${successes} success, ${failures} failure(s)`
        });
    }

    return successes > 0;
};

