private handleEscalation = (incidentId: string, monitor: Monitor, monitorStatusResponse?: MonitorStatusResponse) => {
		this.cancelEscalation(incidentId);

		const escalationAfterMinutes = typeof (monitor as any).escalationAfter === "number" && (monitor as any).escalationAfter > 0
			? (monitor as any).escalationAfter
			: 0.0833333333; // 5 seconds default as 1/12 of a minute

		const baseDelay = escalationAfterMinutes * 60 * 1000;
		const escalationTimerConfig = [
			{ delay: baseDelay * 1, level: 1 },
			{ delay: baseDelay * 2, level: 2 },
			{ delay: baseDelay * 3, level: 3 },
		];

		const timers: NodeJS.Timeout[] = [];
		const escalationResponse = this.buildEscalationStatusResponse(monitor, monitorStatusResponse);

		for (const step of escalationTimerConfig) {
			const timer = setTimeout(async () => {
				try {
					const activeIncident = await this.incidentsRepository.findActiveByIncidentId(incidentId, monitor.teamId);
					if (!activeIncident || !activeIncident.status) {
						this.logger.debug({
							service: SERVICE_NAME,
							method: "handleEscalation",
							message: "Skipping escalation because incident no longer active",
							details: { incidentId },
						});
						return;
					}

					const escalationDecision: MonitorActionDecision = {
						shouldCreateIncident: false,
						shouldResolveIncident: false,
						shouldSendNotification: true,
						incidentReason: null,
						notificationReason: "status_change",
					};

					const success = await this.notificationsService.handleNotifications(
						monitor,
						escalationResponse,
						escalationDecision
					);

					this.logger.info({
						service: SERVICE_NAME,
						method: "handleEscalation",
						message: `Escalation level ${step.level} executed for incident ${incidentId}`,
						details: { incidentId, level: step.level, success },
					});
				} catch (error: unknown) {
					this.logger.error({
						service: SERVICE_NAME,
						method: "handleEscalation",
						message: error instanceof Error ? error.message : "Unknown error",
						details: { incidentId, level: step.level },
						stack: error instanceof Error ? error.stack : undefined,
					});
				}
			}, step.delay);

			timers.push(timer);
		}

		this.escalationTimers.set(incidentId, timers);
	};

	private cancelEscalation = (incidentId: string) => {
		const timers = this.escalationTimers.get(incidentId);
		if (!timers) {
			return;
		}

		timers.forEach(clearTimeout);
		this.escalationTimers.delete(incidentId);
	};

	private buildEscalationStatusResponse = (monitor: Monitor, monitorStatusResponse?: MonitorStatusResponse): MonitorStatusResponse => {
		return (
			monitorStatusResponse ?? {
				monitorId: monitor.id,
				teamId: monitor.teamId,
				type: monitor.type,
				status: monitor.status === "up",
				code: -1,
				message: "Escalation notification",
			}
		);
	};

